function номераСтраниц(текст){
return всего => {
const т = String(текст || '').trim().toLowerCase().replace(/\s*[-–—]\s*/g, '-');
if(!т || /^(все|всё)$/.test(т)) return [...Array(всего).keys()];
const out = new Set();
for(const кус of т.split(/[,;\s]+/).filter(Boolean)){ const м = кус.match(/^(\d*)-(\d*)$/); if(м){ for(let k = +(м[1] || 1); k <= Math.min(+(м[2] || всего), всего); k++) out.add(k - 1); } else if(/^\d+$/.test(кус) && +кус <= всего) out.add(+кус - 1); }
